export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type Step =
  | { op: "quote"; items: Item[] }
  | {
      op: "claim";
      policy: number;
      incident: { cause: string; damages: { itemType: string; amount: number }[] };
    };

export function runScenario(scenario: Scenario): { results: unknown[] } {
  return { results: [] };
}

