const COMPONENTS: Record<string, number> = { rune: 25 };
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

function isComponent(item: Item): boolean {
  return item.type in COMPONENTS;
}

function basePremiumFor(items: Item[]): number {
  const componentCounts = new Map<string, number>();
  let total = 0;
  for (const item of items) {
    if (isComponent(item)) {
      const count = (componentCounts.get(item.type) ?? 0) + 1;
      componentCounts.set(item.type, count);
    } else {
      total += BASE_PREMIUMS[item.type];
    }
  }
  for (const [type, count] of componentCounts) {
    total += count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_PREMIUM : count * (COMPONENTS[type] ?? 0);
  }
  return total;
}

function quotePremium(items: Item[]): number {
  const base = basePremiumFor(items);
  const firstInsuranceSurcharge = FIRST_INSURANCE_RATE * base;
  return base + firstInsuranceSurcharge + PROCESSING_FEE;
}

