input.newString:
function quotePremium(yearsWithMHPCO: number, items: Item[]): number {
  const base = computeBasePremium(items);
  const surcharges = computeItemSurcharges(items);
  const firstInsuranceSurcharge = FIRST_INSURANCE_RATE * base;
  const loyaltyDiscount =
    yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
      ? LOYALTY_DISCOUNT_RATE * base
      : 0;
  return Math.ceil(
    base + surcharges + firstInsuranceSurcharge - loyaltyDiscount + PROCESSING_FEE
  );
}

export function runScenario(scenario: Scenario): { results: unknown[] } {
  const results = scenario.steps.map((step) => {
    if (step.op === "quote") {
      return { premium: quotePremium(scenario.customer.yearsWithMHPCO, step.items) };
    }
    return {};
  });
  return { results };
}

