  let total = 0;
  for (const item of items) {
    const base = itemBasePremium(item);
    if (item.cursed) {
      total += CURSE_RATE * base;
    }
    if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD) {
      total += HIGH_ENCHANTMENT_RATE * base;
    }
  }
  return total;
}

